from pathlib import Path
import json
from urllib.parse import quote
from .dashboard import esc
CATALOG=json.loads(Path(__file__).with_name('console_catalog.json').read_text(encoding='utf-8'))
EDITOR=Path(__file__).with_name('console_editor.js').read_text(encoding='utf-8')
SCRIPT=Path(__file__).with_name('console.js').read_text()+'\n'+EDITOR.replace('/*CONSOLE_CATALOG*/{}',json.dumps(CATALOG,ensure_ascii=False).replace('<','\\u003c'))




def icon(name):
    paths={'terminal':'m4 5 6 7-6 7m9 0h7','play':'m8 5 11 7-11 7Z','clear':'m4 16 9-12 7 5-9 12H5l-3-3 2-2m4-5 7 5m0 5h7','history':'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2','code':'m8 5-6 7 6 7m8-14 6 7-6 7m-3-17-2 20','send':'m3 3 19 9-19 9 4-9-4-9Zm4 9h15','stop':'M6 6h12v12H6Z'}
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+('<path d="'+paths[name]+'"/>')+'</svg>'


def section(agent,csrf,data):
    info=data.get('console')
    if data.get('agent_platform')=='portal':return ''
    body='<section class="server terminal-panel" id="remote-console" data-protected-pane data-shell="'+esc((info or {}).get('shell',''))+'" data-url="/api/servers/'+esc(quote(agent,safe=''))+'/console" data-agent="'+esc(agent)+'"><h2>Мини-консоль</h2>'
    if not info:return body+'<p class="muted">Обновите агент для поддержки консоли.</p></section>'
    shell='PowerShell' if info.get('shell')=='powershell' else 'Bash'
    body+='<div class="terminal-window"><div class="terminal-titlebar"><div class="terminal-session">'+icon('terminal')+'<span>'+shell+'</span><span class="terminal-host">'+esc(agent)+'</span></div><span class="terminal-state" data-console-state role="status">Подключение…</span></div>'
    body+='<div class="terminal-identity"><span>'+esc(info.get('identity') or 'Пользователь неизвестен')+'</span><span>HTTPS · агент</span></div>'
    if not info.get('streaming'):body+='<p class="terminal-note">Обновите агент для живого вывода; текущая версия отправляет результат после завершения.</p>'
    if not info.get('enabled'):body+='<p class="notice">Консоль выключена на агенте. Включите allow_remote_console локально и перезапустите службу. См. deploy/CONSOLE.md.</p>'
    else:
        body+='<form id="console-form"><input type="hidden" name="csrf" value="'+esc(csrf)+'"><div class="terminal-command-heading"><label for="console-command">Командный ввод</label><kbd>Ctrl ↵</kbd></div><div class="terminal-command-line"><span class="terminal-prompt" aria-hidden="true">'+('PS ❯' if info.get('shell')=='powershell' else '$')+'</span><div class="console-editor"><textarea id="console-command" name="command" rows="4" maxlength="4000" required spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" aria-autocomplete="list" aria-controls="console-completions" aria-expanded="false" aria-describedby="console-editor-help" placeholder="'+('Get-Service | Select-Object -First 10' if info.get('shell')=='powershell' else 'uptime; df -h /')+'"></textarea><div id="console-completions" class="console-completions" role="listbox" aria-label="Подсказки команд" hidden></div></div></div><div class="terminal-editor-footer"><button type="button" class="terminal-button terminal-quiet" id="console-show-hints" title="Подсказки команд · Ctrl+Пробел">'+icon('code')+'<span>Подсказки</span></button><span id="console-editor-count" role="status"></span></div><div class="terminal-runbar"><label class="terminal-timeout">Таймаут<select name="timeout"><option value="15">15 с</option><option value="30" selected>30 с</option><option value="60">60 с</option></select></label><label class="check terminal-confirm"><input type="checkbox" name="confirmation" required> Разрешаю запуск на <b>'+esc(agent)+'</b></label><button type="submit" class="terminal-button terminal-run" title="Запустить команды · Ctrl+Enter">'+icon('play')+'<span data-console-run-label>Запустить</span></button></div><button type="button" class="terminal-button terminal-review" id="console-review" hidden>Результат проверен локально — разрешить новую команду</button></form>'
        body+='<form id="console-input-form" class="terminal-input-form" hidden><label for="console-stdin">Ввод работающему процессу</label><div class="terminal-stdin-row"><span class="terminal-prompt" aria-hidden="true">↳</span><input id="console-stdin" name="stdin" maxlength="1024" autocomplete="off" placeholder="Ответ процессу…"><button type="submit" class="terminal-button" title="Отправить строку">'+icon('send')+'<span>Отправить</span></button></div><div class="terminal-input-actions"><button type="button" class="terminal-button terminal-quiet" data-console-eof title="Завершить ввод процесса">EOF</button><button type="button" class="terminal-button terminal-danger" data-console-cancel>'+icon('stop')+'<span>Остановить</span></button><span>Пароли в защищённом режиме не поддерживаются</span></div></form>'
    body+='<p id="console-message" class="terminal-message" role="status" aria-live="polite"></p><div class="terminal-output-toolbar"><span class="terminal-output-label">Вывод <span id="console-scope">за последний час</span></span><div class="terminal-output-actions"><button type="button" class="terminal-button terminal-quiet" id="console-clear" title="Скрыть завершённые записи на экране; архив сохранится">'+icon('clear')+'<span>Очистить экран</span></button><button type="button" class="terminal-button terminal-quiet" id="console-archive" title="История за последние 6 месяцев">'+icon('history')+'<span data-console-archive-label>Вся история</span></button></div></div><div id="console-history" class="terminal-history"></div><button type="button" class="terminal-button terminal-more" id="console-more" hidden>Загрузить ещё записи</button></div>'
    body+='<details class="terminal-help"><summary>Горячие клавиши и особенности запуска</summary><div id="console-editor-help"><p>Enter — новая строка · Ctrl+Enter — выполнить блок · Ctrl+Пробел — подсказки · ↑/↓ — выбор · Tab/Enter — вставить · Esc — закрыть. Поиск по имени и русскому описанию; после пробела — параметры команды.</p><p>Один запуск за раз. Все строки блока выполняются в одной оболочке; cd и переменные между ними сохраняются. Между отдельными запусками состояние не сохраняется. Рабочая папка — каталог конфигурации агента. Лимит времени и вывода общий на весь блок; команды выполняются с правами учётной записи службы.</p><p>Подсказки только вставляют текст и не проверяют наличие команды на сервере. Вывод появляется по мере выполнения при поддержке агентом. Команды и вывод хранятся в истории; очистка экрана не удаляет архив.</p></div></details></section><script data-protected-script>'+SCRIPT+'</script>'
    return body
